  ('page-home', 'home', 'Dakzo Systems', 'published',
   '{"heroEyebrow":"A Dakik LLC Company","heroTitle":"We build systems that run businesses.","intro":"Dakzo Systems designs and builds custom software, ERP platforms, web applications, mobile applications, logistics technology, tracking systems, and business automation.","featuredProjectSlug":"hmd-erp","sections":[{"heading":"Selected work","body":"HMD ERP, Congo Delivery, and Moto Track demonstrate how Dakzo turns operational requirements into working software."},{"heading":"Built around operations","body":"We design products around real workflows, clear interfaces, dependable engineering, and long-term maintainability."}],"primaryCta":{"label":"Start a project","href":"/contact/"},"secondaryCta":{"label":"See our work","href":"/work/"}}',
   'Dakzo Systems | Custom Software, ERP & Applications',
   'Dakzo Systems builds custom software, ERP platforms, web and mobile applications, logistics technology, tracking systems, and business automation.',
   '/', CURRENT_TIMESTAMP),
  ('page-about', 'about', 'About Dakzo Systems', 'published',
   '{"heroEyebrow":"About Dakzo","heroTitle":"Technology built for real operations.","intro":"Dakzo Systems is the software and technology subsidiary of Dakik LLC, focused on designing and building digital systems, products, and platforms.","featuredProjectSlug":"","sections":[{"heading":"What we build","body":"Custom software, ERP, business systems, websites, applications, logistics technology, tracking platforms, and automation."},{"heading":"How we work","body":"We combine product thinking, interface design, business logic, and engineering around the operating reality of each project."}],"primaryCta":{"label":"View our work","href":"/work/"},"secondaryCta":{"label":"Start a project","href":"/contact/"}}',
   'About Dakzo Systems | A Dakik LLC Company',
   'Learn about Dakzo Systems, the software and technology subsidiary of Dakik LLC building custom digital systems and applications.',
   '/about/', CURRENT_TIMESTAMP),
  ('page-services', 'services', 'Dakzo Systems Services', 'published',
   '{"heroEyebrow":"Services","heroTitle":"Software engineering around your business.","intro":"Dakzo Systems builds custom digital products from operational discovery through design, engineering, deployment, and iteration.","featuredProjectSlug":"hmd-erp","sections":[{"heading":"Custom software","body":"Purpose-built systems for workflows that generic tools do not fit."},{"heading":"ERP and business systems","body":"Inventory, finance, operations, logistics, reporting, production, and connected workflows."},{"heading":"Web and mobile applications","body":"Responsive products designed for real users across desktop, tablet, and mobile."}],"primaryCta":{"label":"Start a project","href":"/contact/"},"secondaryCta":{"label":"Explore solutions","href":"/solutions/"}}',
   'Software Development Services | Dakzo Systems',
   'Explore Dakzo Systems services for custom software, ERP platforms, web applications, mobile applications, logistics systems, and automation.',
   '/services/', CURRENT_TIMESTAMP),
  ('page-solutions', 'solutions', 'Dakzo Systems Solutions', 'published',
   '{"heroEyebrow":"Solutions","heroTitle":"Systems designed around the way work actually happens.","intro":"We create digital systems for operations, logistics, inventory, tracking, finance, delivery, and business automation.","featuredProjectSlug":"congo-delivery","sections":[{"heading":"ERP and operations","body":"Connected business workflows spanning data, approvals, reporting, stock, finance, and teams."},{"heading":"Logistics and delivery","body":"Dispatch, tracking, operational visibility, customer workflows, and logistics coordination."},{"heading":"Tracking platforms","body":"Maps, assets, alerts, history, reporting, and mobile operational visibility."}],"primaryCta":{"label":"View selected work","href":"/work/"},"secondaryCta":{"label":"Talk to Dakzo","href":"/contact/"}}',
   'Business Software Solutions | Dakzo Systems',
   'Dakzo Systems creates ERP, logistics, tracking, inventory, delivery, and business automation solutions built around real operations.',
   '/solutions/', CURRENT_TIMESTAMP),
  ('page-contact', 'contact', 'Start a Project | Dakzo Systems', 'published',
   '{"heroEyebrow":"Start a project","heroTitle":"Tell us what you need to build.","intro":"Share the problem, workflow, product idea, timeline, and requirements. Dakzo can turn the brief into a structured software project.","featuredProjectSlug":"","sections":[{"heading":"Good starting information","body":"Describe the users, workflow, current problem, desired result, important integrations, timeline, and any existing system constraints."}],"primaryCta":{"label":"Explore our work","href":"/work/"},"secondaryCta":{"label":"About Dakzo","href":"/about/"}}',
