   '/contact/', CURRENT_TIMESTAMP);

INSERT OR IGNORE INTO cms_articles (id, slug, title, excerpt, status, content_json, seo_title, seo_description, published_at)
VALUES
  ('article-custom-erp', 'custom-erp-vs-off-the-shelf', 'Custom ERP vs. off-the-shelf ERP',
   'A practical framework for deciding whether a business should adapt to packaged ERP software or invest in a system designed around its operations.',
   'published',
   '{"category":"ERP","body":"Off-the-shelf ERP can be a strong fit when a company follows standard processes and wants faster implementation. Custom ERP becomes more valuable when operations contain unique workflows, integrations, permissions, costing logic, or reporting needs that generic software forces the business to work around.\n\nThe decision should compare long-term operational fit, implementation risk, change management, integration requirements, ownership, and the cost of maintaining workarounds.","relatedProjectSlug":"hmd-erp","takeaways":["Choose based on operational fit, not feature count.","Include integration and workflow costs in the comparison.","Custom ERP is strongest when unique processes create real competitive or operational value."]}',
   'Custom ERP vs Off-the-Shelf ERP | Dakzo Systems',
   'Compare custom ERP and off-the-shelf ERP by operational fit, integrations, workflow complexity, ownership, implementation, and long-term value.', CURRENT_TIMESTAMP),
  ('article-custom-software', 'when-custom-software-is-worth-it', 'When custom software is worth it',
   'How to recognize when spreadsheets, disconnected tools, or rigid SaaS products are creating enough operational friction to justify custom software.',
   'published',
   '{"category":"Custom Software","body":"Custom software is most valuable when a recurring operational problem cannot be solved cleanly with existing products. Warning signs include repeated manual reconciliation, duplicate data entry, fragile spreadsheets, permission gaps, disconnected systems, and workflows that employees must constantly work around.\n\nA strong custom-software project starts with the business process and measurable operating problem rather than a list of desired screens.","relatedProjectSlug":"hmd-erp","takeaways":["Start with the operating problem.","Measure the cost of the current workaround.","Build the smallest system that removes meaningful friction first."]}',
   'When Custom Software Is Worth It | Dakzo Systems',
   'Learn when custom software makes business sense and how to evaluate workflow friction, manual work, integrations, risk, and long-term value.', CURRENT_TIMESTAMP),
  ('article-logistics', 'how-logistics-platforms-work', 'How logistics platforms connect operations',
   'A look at how modern logistics platforms connect order intake, dispatch, tracking, operational visibility, and customer workflows.',
   'published',
   '{"category":"Logistics Technology","body":"A logistics platform becomes useful when it creates one operating picture across orders, dispatch, vehicles or riders, status changes, exceptions, and customer communication. The system should reduce the number of places where teams must check or re-enter the same information.\n\nGood logistics software also makes responsibility and state transitions clear, so operators know what is waiting, assigned, moving, delayed, completed, or needs attention.","relatedProjectSlug":"congo-delivery","takeaways":["Connect order, dispatch, and tracking states.","Make exceptions visible early.","Design the interface around operators as well as customers."]}',
   'How Logistics Platforms Work | Dakzo Systems',
   'Understand how logistics software connects order intake, dispatch, tracking, operational visibility, exceptions, and customer communication.', CURRENT_TIMESTAMP),
  ('article-fleet-tracking', 'how-fleet-tracking-systems-work', 'How fleet tracking systems work',
   'The core product and operational components behind fleet and motorcycle tracking systems, from location events to alerts, history, and reporting.',
   'published',
   '{"category":"Tracking Technology","body":"Fleet tracking software turns a stream of location and device events into operational information. The useful product is not only a moving dot on a map; it includes asset identity, current state, history, alerts, search, reporting, permissions, and mobile access.\n\nThe best tracking interfaces help operators understand what changed and what action is needed without overwhelming them with raw telemetry.","relatedProjectSlug":"moto-track","takeaways":["Tracking is an operational workflow, not only a map.","History and alerts are as important as current position.","Design around decisions operators need to make."]}',
   'How Fleet Tracking Systems Work | Dakzo Systems',
   'Learn how fleet tracking systems combine location events, maps, alerts, history, reporting, permissions, and operational workflows.', CURRENT_TIMESTAMP);
